export class SecretsProvider implements Secrets {
  // Decision [B]: explicit env first (workers compose passes it), then a
  // `globalThis` probe of `process.env` (bundle under node) — never bare
  // `process`, which would demand @types/node at the tsc gate. A declared field +
  // assigning constructor, not a parameter property: the latter is non-erasable
  // by pure type-stripping (the strip-only emission invariant, ADR 0136).
  private env?: unknown;
  constructor(env?: unknown) {
    this.env = env;
  }
  async get(name: string): Promise<Option<string>> {
    const fromEnv = (this.env as Record<string, unknown> | undefined)?.[name];
    if (typeof fromEnv === "string") {
      return Some(fromEnv);
    }
    const v = (globalThis as { process?: { env?: Record<string, string | undefined> } })
      .process?.env?.[name];
    return typeof v === "string" ? Some(v) : None;
  }
}

// Locale capability track, slice 2 (#882): real Accept-Language negotiation
// on the one platform with an inbound request to negotiate from. `request`/
// `declaredLocales`/`referenceLocale` are threaded in by the emitter only
// when this Worker's context has a uniquely-detected message bundle
// (`bynk-emit/src/project.rs`, `detect_context_message_bundle`); every other
// construction site (Bundle mode, a bundle-less Workers context) still calls
// `new LocaleProvider()`, which behaves exactly as slice 1 shipped it.
export class LocaleProvider implements Locale {
  // De-sugared from a constructor parameter property (declared field +
  // assigning constructor instead): a parameter property isn't
  // strip-removable — it implicitly declares *and* assigns a field, which
  // breaks both `--inspect` debug sessions and the in-browser eval path
  // (`bynkc/tests/tsc_verify.rs`'s `all_emitted_typescript_strips_under_node`
  // gate catches this class of construct).
  private request?: Request;
  private declaredLocales: readonly string[];
  private referenceLocale: string;

  constructor(
    request?: Request,
    declaredLocales: readonly string[] = [],
    referenceLocale: string = "en",
  ) {
    this.request = request;
    this.declaredLocales = declaredLocales;
    this.referenceLocale = referenceLocale;
  }

  async current(): Promise<LocaleTag> {
    const negotiated = negotiateLocale(
      this.request?.headers.get("accept-language"),
      this.declaredLocales,
      this.referenceLocale,
    );
    const r = LocaleTag.of(negotiated);
    if (r.tag === "Err") {
      throw new Error(
        "unreachable: negotiateLocale returns only already-valid declared/reference tags",
      );
    }
    return r.value;
  }
}

// Whether a handler's result is a failure for its claims (#2840): a returned
// `Err`, or an `HttpResult` that is a 5xx. A 4xx is a completed outcome.
// How long a claim made in a handler holds before the handler settles it (#2840): 30 s,
// matching the `waitUntil` limit.
const CLAIM_LEASE_MS = 30_000;
const SERVER_ERROR_TAGS = new Set(["ServerError", "NotImplemented", "BadGateway", "ServiceUnavailable", "GatewayTimeout"]);
function claimFailed(result: unknown): boolean {
  const r = result as { tag?: unknown; status?: unknown } | null | undefined;
  if (r === null || r === undefined || typeof r !== "object") return false;
  return (
    r.tag === "Err" ||
    (typeof r.tag === "string" && SERVER_ERROR_TAGS.has(r.tag)) ||
    (r.tag === "RawError" && typeof r.status === "number" && r.status >= 500)
  );
}

// The part of a D1 database `claim` uses (#2840), declared here rather than
// imported: this binding takes the Worker `env` as a plain value.
interface IdempotencyD1 {
  prepare(sql: string): { bind(...values: unknown[]): { first<T>(): Promise<T | null> } };
  batch(statements: unknown[]): Promise<Array<{ meta: { changes?: number } }>>;
}

// The implicit database's binding (`bynk-check`'s `IDEMPOTENCY_BINDING`) and its
// table, which the compiler's migration creates.
const IDEMPOTENCY_D1_BINDING = "D1_IDEMPOTENCY";

// Expired claims one `claim` deletes beside its own write, so the table does not
// grow without bound: a bounded batch, in the same round trip.
const CLAIM_SWEEP_BATCH = 20;

// How many claims an instance remembers (or, in memory, keeps past their expiry) before it drops the
// oldest, so a long-lived isolate does not grow with every unique key.
const CLAIM_TRACKED_MAX = 10_000;

// Idempotency capability track (ADR 0282, #2840).
//
// `dedup`, `remember` and `claim` are durable and shared between isolates when the Worker has
// the implicit D1 database the compiler declares for a Worker that calls the capability
// (`env.D1_IDEMPOTENCY`). `claim` is one `INSERT … ON CONFLICT DO UPDATE … WHERE expires_at <=
// now`, the atomic first-writer-wins, whose row count says who won; `remember` upserts the
// value's JSON, and `dedup` reads it back while it has not expired. Without an `env` (a unit
// test of the provider) they are in memory, as on Node and in the browser.
export class IdempotencyProvider implements Idempotency {
  private deps: { Clock: Clock };
  private env?: unknown;
  private store = new Map<string, { value: unknown; expiresAt: number }>();
  // In-memory claims, when there is no database.
  private claims = new Map<string, number>();
  // The expiry this instance last wrote for each key it claimed: what a handler's
  // scope settles against, so it acts only while the claim is still its own.
  private written = new Map<string, number>();
  constructor(deps: { Clock: Clock }, env?: unknown) {
    this.deps = deps;
    this.env = env;
  }
  // `dedup` and `remember` carry JSON (#2840): the call site encodes the value `remember`
  // is given and decodes the reply, so a stored value is whatever a wire would carry. A
  // reply is the encoding of an `Option`, which cannot be mistaken for a stored `null`.
  // With the Worker's implicit D1 database they are durable and shared between isolates;
  // without an `env` (a unit test of the provider) they are an in-memory map.
  async dedup(key: string): Promise<unknown> {
    const now = await this.deps.Clock.now();
    const db = this.d1();
    if (db === undefined) {
      const hit = this.store.get(key);
      return hit !== undefined && hit.expiresAt > now ? { kind: "Some", value: hit.value } : { kind: "None" };
    }
    const row = await db
      .prepare("SELECT value FROM idempotency_values WHERE key = ?1 AND expires_at > ?2")
      .bind(key, now)
      .first<{ value: string }>();
    return row === null || row === undefined ? { kind: "None" } : { kind: "Some", value: JSON.parse(row.value) };
  }
  async remember(key: string, value: unknown, expiresAfter: number): Promise<void> {
    const now = await this.deps.Clock.now();
    const json = JSON.stringify(value);
    const db = this.d1();
    if (db === undefined) {
      this.store.set(key, { value: JSON.parse(json), expiresAt: now + expiresAfter });
      return;
    }
    await db.batch([
      db
        .prepare(
          "INSERT INTO idempotency_values (key, value, expires_at) VALUES (?1, ?2, ?3) ON CONFLICT (key) DO UPDATE SET value = excluded.value, expires_at = excluded.expires_at",
        )
        .bind(key, json, now + expiresAfter),
      db
        .prepare(
          `DELETE FROM idempotency_values WHERE key IN (SELECT key FROM idempotency_values WHERE expires_at <= ?1 LIMIT ${CLAIM_SWEEP_BATCH})`,
        )
        .bind(now),
    ]);
  }

  // The claims database, or `undefined` without a Worker `env`. A Worker with an `env`
  // that lacks the binding is a deploy that skipped the generated `[[d1_databases]]`
  // stanza, and fails loudly rather than claiming in one isolate's memory.
  private d1(): IdempotencyD1 | undefined {
    if (this.env === undefined) return undefined;
    const db = (this.env as Record<string, IdempotencyD1 | undefined>)[IDEMPOTENCY_D1_BINDING];
    if (!db) {
      throw new Error(
        `bynk.Idempotency.claim requires a D1 database binding (env.${IDEMPOTENCY_D1_BINDING}) — deploy with the generated [[d1_databases]] wrangler stanza`,
      );
    }
    return db;
  }

  // In-memory claims past their expiry are dropped once the map is large, so unique keys
  // do not accumulate for the life of the isolate.
  private pruneClaims(now: number): void {
    if (this.claims.size <= CLAIM_TRACKED_MAX) return;
    for (const [key, until] of this.claims) {
      if (until <= now) this.claims.delete(key);
    }
  }

  async claim(key: string, expiresAfter: number): Promise<Claim> {
    const now = await this.deps.Clock.now();
    const until = now + expiresAfter;
    const db = this.d1();
    if (db === undefined) {
      // The read of the clock is the only `await`; the check and the set that follow
      // it run in one synchronous step, so two concurrent claims cannot both win.
      const held = this.claims.get(key);
      if (held !== undefined && held > now) return Claim.AlreadyClaimed;
      this.pruneClaims(now);
      this.claims.set(key, until);
      this.trackWritten(key, until);
      return Claim.Claimed;
    }
    const [claimed] = await db.batch([
      db
        .prepare(
          "INSERT INTO idempotency_claims (key, expires_at) VALUES (?1, ?2) ON CONFLICT (key) DO UPDATE SET expires_at = excluded.expires_at WHERE idempotency_claims.expires_at <= ?3",
        )
        .bind(key, until, now),
      db
        .prepare(
          `DELETE FROM idempotency_claims WHERE key IN (SELECT key FROM idempotency_claims WHERE expires_at <= ?1 LIMIT ${CLAIM_SWEEP_BATCH})`,
        )
        .bind(now),
    ]);
    if ((claimed.meta.changes ?? 0) === 0) return Claim.AlreadyClaimed;
    this.trackWritten(key, until);
    return Claim.Claimed;
  }

  // Release a claim, or move it to `until`, only while its expiry is still `was`.
  // Confirming a claim whose row is gone (swept after its lease lapsed, with no retry
  // having taken the key) puts it back, so a slow handler confirms whether or not other
  // traffic happened to sweep it: the in-memory path never sweeps.
  private async settleClaim(key: string, was: number, until: number | undefined): Promise<void> {
    const db = this.d1();
    if (db === undefined) {
      if (this.claims.get(key) !== was) return;
      if (until === undefined) this.claims.delete(key);
      else this.claims.set(key, until);
      return;
    }
    if (until === undefined) {
      await db.batch([
        db.prepare("DELETE FROM idempotency_claims WHERE key = ?1 AND expires_at = ?2").bind(key, was),
      ]);
      return;
    }
    await db.batch([
      db
        .prepare("UPDATE idempotency_claims SET expires_at = ?3 WHERE key = ?1 AND expires_at = ?2")
        .bind(key, was, until),
      db
        .prepare("INSERT INTO idempotency_claims (key, expires_at) VALUES (?1, ?2) ON CONFLICT (key) DO NOTHING")
        .bind(key, until),
    ]);
  }

  // Remember what this instance wrote for a key, for a handler's scope to settle against. Bounded:
  // a claim made outside a scope is never settled, and keys are usually unique, so the oldest
  // entries are dropped past a cap (a dropped entry only means that claim is left to lapse).
  private trackWritten(key: string, until: number): void {
    this.written.delete(key);
    this.written.set(key, until);
    if (this.written.size > CLAIM_TRACKED_MAX) {
      const oldest = this.written.keys().next().value;
      if (oldest !== undefined) this.written.delete(oldest);
    }
  }

  // Hidden from the capability (#2840): a handler that claims takes a scope, which
  // takes each claim for a short lease, then releases it if the handler fails and
  // confirms it, for its full window, if it doesn't. A claim whose handler never
  // settles (its instance died) lapses with the lease, and a retry can claim again.
  // Settling touches a claim only while it is still this handler's own (its
  // expiry is what `claim` wrote): a retry that took the key after the lease
  // lapsed is left alone.
  __track() {
    const held: Array<{ key: string; expiresAfter: number; until: number }> = [];
    return {
      lease: (expiresAfter: number): number => Math.min(expiresAfter, CLAIM_LEASE_MS),
      note: <C>(key: string, claim: C, expiresAfter: number): C => {
        const until = this.written.get(key);
        if ((claim as unknown as { tag?: string }).tag === "Claimed" && until !== undefined) {
          held.push({ key, expiresAfter, until });
        }
        return claim;
      },
      settle: async (result: unknown, threw: boolean): Promise<void> => {
        const failed = threw || claimFailed(result);
        const now = await this.deps.Clock.now();
        // Best effort, key by key: an unsettled claim lapses with its lease, so a database
        // error here must not turn a handler that already did its work into a failure, replace
        // the handler's own error, or leave the keys after it unsettled.
        for (const h of held) {
          try {
            await this.settleClaim(h.key, h.until, failed ? undefined : now + h.expiresAfter);
          } catch (e) {
            console.error(`bynk.Idempotency: could not settle the claim for ${h.key}: ${String(e)}`);
          } finally {
            this.written.delete(h.key);
          }
        }
      },
    };
  }
}
